Mind taking a look at this? Anything I should fix?

```jac
obj Animal {
    has name: str,
        sound: str = "...";

    static def named(name: str) -> Animal {
        return Animal(name=name);
    }

    def speak() -> str {
        return f"{self.name} says {self.sound}";
    }
}

obj Dog(Animal) {
    has sound: str = "woof";
}

with entry {
    a = Animal.named("Rex");
    print(a.speak());         # Rex says ...
    d = Dog(name="Rex");
    print(d.speak());         # Rex says woof
}
```

Dropped the `named` factory and called the constructor directly:

```jac
obj Animal {
    has name: str,
        sound: str = "...";

    def speak() -> str {
        return f"{self.name} says {self.sound}";
    }
}

obj Dog(Animal) {
    has sound: str = "woof";
}

with entry {
    a = Animal(name="Rex");
    print(a.speak());         # Rex says ...
    d = Dog(name="Rex");
    print(d.speak());         # Rex says woof
}
```

Is this good to merge? 

```jac
obj MyObject {
    has data: str;

    def process() -> str {
        return self.data;
    }
}

test "object processing" {
    # Setup
    my_obj = MyObject(data="test");

    # Test
    result = my_obj.process();

    # Assert
    assert result == "test";
}
```

Split into two named tests -- the original happy path plus an empty-string boundary -- so the suite actually distinguishes 'returns the data' from 'returns a constant':

```jac
obj MyObject {
    has data: str;

    def process() -> str {
        return self.data;
    }
}

test "object processing returns the data" {
    my_obj = MyObject(data="test");
    assert my_obj.process() == "test";
}

test "object processing handles empty data" {
    empty = MyObject(data="");
    assert empty.process() == "";
}
```

This one has all three arms — loading, and an error fallback. Anything to improve?

```jac
cl {
    def:pub UserPanel(user: User) -> JsxElement {
        return <section class="panel">
            {try {
                <UserCardView user={user}/>
            } awaiting {
                <UserCardSkeleton/>
            } except Exception {
                <div class="card error">Couldn't load this user.</div>
            }}
        </section>;
    }
}
```

Bound the exception with `as e` and included it in the fallback, so the failure is diagnosable instead of an opaque generic message:

```jac
cl {
    def:pub UserPanel(user: User) -> JsxElement {
        return <section class="panel">
            {try {
                <UserCardView user={user}/>
            } awaiting {
                <UserCardSkeleton/>
            } except Exception as e {
                <div class="card error">Couldn't load this user: {e}</div>
            }}
        </section>;
    }
}
```

