`create_todo` now takes `priority` in its request body, and `tid spawn set_priority(priority=2)` updates one in place.

Can you review this? 

```jac
def divide(a: float, b: float) -> float {
    if b == 0 {
        raise ValueError("Cannot divide by zero");
    }
    return a / b;
}

with entry {
    try {
        result = divide(10, 0);
    } except ValueError as e {
        print(f"Error: {e}");
    } finally {
        print("Done");
    }
}
```

Moved the `print` of `result` inside the `try` right after the successful division, so the computed value is actually shown (and the assignment isn't dead):

```jac
def divide(a: float, b: float) -> float {
    if b == 0 {
        raise ValueError("Cannot divide by zero");
    }
    return a / b;
}

with entry {
    try {
        result = divide(10, 0);
        print(f"Result: {result}");
    } except ValueError as e {
        print(f"Error: {e}");
    } finally {
        print("Done");
    }
}
```

Use `report here` to collect a node into the results, guarded by the age check, and read `result.reports` after spawning:

```jac
node Person {
    has name: str;
    has age: int;
}

walker FindAdults {
    can start with Root entry {
        visit [-->];
    }

    can check with Person entry {
        if here.age >= 18 {
            report here;
        }
        visit [-->];
    }
}

with entry {
    root ++> Person(name="Alice", age=30);
    root ++> Person(name="Bob", age=15);
    result = root spawn FindAdults();
    print(len(result.reports));
}
```

