You're right -- I scaled by the width but forgot to shift by `lo`. It needs `lo + rand01() * (hi - lo)` so the sample actually starts at the low bound. Fixed, with an entry block sampling a few intervals (rounded to 6 dp so the output is stable):

```jac
"""Seeded-LCG uniform RNG: rand01() in [0,1) and rand_range(lo, hi) scaled into [lo, hi)."""

glob rng: int = 987654321;

def rand01 -> float {
    global rng;
    rng = (rng * 1103515245 + 12345) % 2147483648;
    return float(rng) / 2147483648.0;
}

def rand_range(lo: float, hi: float) -> float {
    return lo + rand01() * (hi - lo);
}

with entry {
