Dict iteration order isn't reliable for tie-breaking, so I'll record first-appearance order and only replace `best` on a strictly higher count:

```jac
def most_common_word(s: str) -> str {
    counts = {};
    order = [];
    for w in s.split() {
        if w in counts {
            counts[w] += 1;
        } else {
            counts[w] = 1;
            order.append(w);
        }
    }
    best = order[0];
    for w in order {
        if counts[w] > counts[best] {
            best = w;
        }
    }
    return best;
}

