The binary-extension part of `_should_skip` is really its own concern. Extract it as a `_is_binary` predicate and have `_should_skip` delegate.

```jac
import os;

glob _BINARY_EXTS: set = { ".png", ".wasm", ".so", ".pyc", ".jbc", ".pdf" };  # (abbreviated)

def _should_skip(rel: str) -> bool {
    if "__pycache__" in rel or os.path.basename(rel).startswith(".") {
        return True;
    }
    ext = os.path.splitext(rel)[1].lower();
    if ext in _BINARY_EXTS {
        return True;
    }
    return False;
}
```

Here it is — `_is_binary` owns the extension test, and `_should_skip` short-circuits on `__pycache__`/dotfiles then returns `_is_binary(rel)`:

```jac
"""_should_skip: binary-extension test extracted into its own predicate."""

import os;

glob _BINARY_EXTS: set = {
    ".png", ".jpg", ".jpeg", ".gif", ".ico", ".webp", ".bmp",
    ".woff", ".woff2", ".ttf", ".otf", ".eot",
    ".wasm", ".so", ".dylib", ".dll", ".a", ".o", ".bin",
    ".zip", ".gz", ".tar", ".pdf", ".mp4", ".mov", ".jbc", ".pyc"
};

def _is_binary(rel: str) -> bool {
    ext = os.path.splitext(rel)[1].lower();
    return ext in _BINARY_EXTS;
}

def _should_skip(rel: str) -> bool {
    if "__pycache__" in rel or os.path.basename(rel).startswith(".") {
        return True;
    }
    return _is_binary(rel);
}

with entry {
    cases = [
        "src/main.jac",
        "a/__pycache__/x.pyc",
        "dir/.hidden",
        "logo.PNG",
        "build/app.wasm",
        "readme.md",
        "nested/.gitignore"
    ];
    for c in cases {
        print(c + " -> " + str(_should_skip(c)));
    }
}
```

