Yes — Jac has this built into the entry-block syntax, so you don't need a manual `__name__` check. A plain `with entry { ... }` runs whenever the module loads (including when it's imported). A `with entry:__main__ { ... }` block runs only when that file is executed directly. Here's the pattern:

```jac
with entry {
    print("Always runs");
}

with entry:__main__ {
    print("Only when this file is main");
}
```

Exactly right — on import you'd see only `Always runs`; the `:__main__` block is skipped because the file isn't the main program in that case. Run it directly and both fire, printing `Always runs` then `Only when this file is main`. Here it is with comments to keep the two straight:

```jac
# Default entry - always runs when this module loads
with entry {
    print("Always runs");
}

# Main entry - only runs when this file is executed directly
# Similar to Python's if __name__ == "__main__"
with entry:__main__ {
    print("Only when this file is main");
}
```

Here's the full step. Outer loop over bullets (advance position by velocity*step and decay life), inner loop over alive targets with the squared-distance test; on a hit it flags the target dead, zeroes the bullet, increments the global `score`, and respawns. The demo fires one overlapping and one far-away bullet and prints the outcome:

```jac
"""Shooter step: advance/age live bullets, resolve squared-distance<1.4 hits against alive targets, tally a global score and respawn hit targets."""

glob rng: int = 987654321,
     score: int = 0;

obj Target {
    has x: float,
        y: float,
        z: float,
        base_y: float,
        phase: float,
        alive: bool;
}

obj Bullet {
    has x: float,
        y: float,
        z: float,
        vx: float,
        vy: float,
        vz: float,
        life: float;
}

"""Uniform pseudo-random float in [0, 1) via a 31-bit LCG."""
def rand01 -> float {
    global rng;
    rng = (rng * 1103515245 + 12345) % 2147483648;
    return float(rng) / 2147483648.0;
}

"""Random float in [lo, hi)."""
def rand_range(lo: float, hi: float) -> float {
    return lo + rand01() * (hi - lo);
}

"""(Re)place a target somewhere in the arena in front of the player (dependency, not the target)."""
def respawn(t: Target) {
    t.x = rand_range(-14.0, 14.0);
    t.base_y = rand_range(1.0, 5.0);
    t.z = rand_range(-16.0, 2.0);
    t.phase = rand_range(0.0, 6.28);
    t.y = t.base_y;
    t.alive = True;
}

def update_bullets(bullets: list[Bullet], targets: list[Target], step: float) {
    global score;
    bi = 0;
    while bi < len(bullets) {
        b = bullets[bi];
        if b.life > 0.0 {
            b.x += b.vx * step;
            b.y += b.vy * step;
            b.z += b.vz * step;
            b.life -= step;
            ti = 0;
            while ti < len(targets) {
                t = targets[ti];
                if t.alive {
                    ddx = b.x - t.x;
                    ddy = b.y - t.y;
                    ddz = b.z - t.z;
                    if ddx * ddx + ddy * ddy + ddz * ddz < 1.4 {
                        t.alive = False;
                        b.life = 0.0;
                        score += 1;
                        respawn(t);
                    }
                }
                ti += 1;
            }
        }
        bi += 1;
    }
}

with entry {
    bullets = [
        Bullet(x=0.0, y=0.0, z=0.0, vx=0.0, vy=0.0, vz=0.0, life=1.0),
        Bullet(x=50.0, y=50.0, z=50.0, vx=0.0, vy=0.0, vz=0.0, life=1.0)
    ];
    targets = [
        Target(x=0.0, y=0.0, z=0.0, base_y=0.0, phase=0.0, alive=True),
        Target(x=-50.0, y=-50.0, z=-50.0, base_y=0.0, phase=0.0, alive=True)
    ];
    update_bullets(bullets, targets, 0.016);
    print(
        str(score) + " " + str(round(targets[0].x, 6)) + " "
        + str(round(targets[0].z, 6)) + " " + str(round(bullets[0].life, 6)) + " "
        + str(targets[0].alive)
    );
}
```

