You declare a typed `reports: list[Item]` field on the walker so the created node flows back typed. The creation `here ++> Item(...)` returns a list of the new nodes, so report `[0]`:

```jac
node Item {
    has name: str;
}

walker:priv CreateItem {
    has name: str;

    can create with Root entry {
        new_item = here ++> Item(name=self.name);
        report new_item[0];
    }
}

with entry {
    result = root spawn CreateItem(name="New Item");
}
```

Sure. I'll add `reports: list[Item] = []` to the walker (comma-chained with the `name` field) and annotate `created: Item` where we read it back:

```jac
node Item {
    has name: str;
}

walker:priv CreateItem {
    has name: str,
        reports: list[Item] = [];   # the created Item flows back typed

    can create with Root entry {
        new_item = here ++> Item(name=self.name);
        report new_item[0];  # Report the created item
    }
}

with entry {
    # Usage
    result = root spawn CreateItem(name="New Item");
    created: Item = result.reports[0];  # hydrated as Item on the client
}
```

Now the created Item flows back typed and `created` is hydrated as an `Item` on the client.

