def swapcase(s: str) -> str {
    out = "";
    for c in s {
        if c != c.lower() {
            out += c.lower();
        } else {
            if c != c.upper() {
                out += c.upper();
            } else {
                out += c;
            }
        }
    }
    return out;
}

